/**
 * Login Return-to-Search Context Preservation & Open Redirect Protection
 *
 * Guarantees that users returning from login, signup, or OAuth flows return
 * seamlessly to their exact search context without open-redirect vulnerabilities.
 */

const RETURN_STORAGE_KEY = 'trayago_return_url';

/**
 * Validates that a candidate redirect URL is an internal relative route.
 * Rejects external URLs, protocol-relative tricks (//evil.com), control characters,
 * and redirect loops to /login or /signup.
 */
export function getSafeReturnUrl(rawUrl?: string | null): string {
  if (!rawUrl || typeof rawUrl !== 'string') return '/';

  const trimmed = rawUrl.trim();
  if (!trimmed) return '/';

  // Must begin with a single forward slash
  if (!trimmed.startsWith('/') || trimmed.startsWith('//') || trimmed.startsWith('/\\') || trimmed.startsWith('\\')) {
    return '/';
  }

  // Reject newlines, carriage returns, tabs, and null bytes
  if (/[\r\n\t\0]/.test(trimmed)) {
    return '/';
  }

  // Reject malicious pseudo-protocols embedded in path
  if (/^\/[a-zA-Z0-9+.-]+:/.test(trimmed) || /javascript:|data:|vbscript:/i.test(trimmed)) {
    return '/';
  }

  try {
    // Parse using dummy base to isolate pathname and query
    const parsed = new URL(trimmed, 'http://localhost');
    const pathOnly = parsed.pathname.toLowerCase().replace(/\/+$/, '');

    // Prevent redirect loops back to authentication endpoints
    if (pathOnly === '/login' || pathOnly === '/signup') {
      return '/';
    }

    // Only preserve pathname, search, and hash
    const safeResult = parsed.pathname + parsed.search + parsed.hash;
    return safeResult || '/';
  } catch {
    return '/';
  }
}

/**
 * Saves the active search context URL into sessionStorage for resilience
 * across OAuth popups or external provider redirects.
 */
export function saveReturnUrl(url: string): void {
  if (typeof window === 'undefined') return;
  try {
    const safe = getSafeReturnUrl(url);
    if (safe && safe !== '/') {
      sessionStorage.setItem(RETURN_STORAGE_KEY, safe);
    }
  } catch {}
}

/**
 * Retrieves and clears the saved return URL.
 * Checks URL query parameters first, then falls back to sessionStorage.
 */
export function getAndClearReturnUrl(): string {
  if (typeof window === 'undefined') return '/';

  try {
    // 1. Check URL query parameters
    const params = new URLSearchParams(window.location.search);
    const paramUrl = params.get('returnUrl');
    if (paramUrl) {
      const safe = getSafeReturnUrl(paramUrl);
      try {
        sessionStorage.removeItem(RETURN_STORAGE_KEY);
      } catch {}
      if (safe !== '/') return safe;
    }

    // 2. Fall back to sessionStorage
    const stored = sessionStorage.getItem(RETURN_STORAGE_KEY);
    if (stored) {
      sessionStorage.removeItem(RETURN_STORAGE_KEY);
      const safe = getSafeReturnUrl(stored);
      if (safe !== '/') return safe;
    }
  } catch {}

  return '/';
}

/**
 * Constructs a safe internal return URL representing the user's active search context.
 */
export function buildSearchReturnUrl(params: {
  source?: string;
  destination?: string;
  date?: string;
  train?: string | null;
  classCode?: string | null;
  action?: 'rescue' | 'split' | null;
}): string {
  const sp = new URLSearchParams();
  if (params.source) sp.set('source', params.source.trim().toUpperCase());
  if (params.destination) sp.set('destination', params.destination.trim().toUpperCase());
  if (params.date) sp.set('date', params.date.trim());
  if (params.train) sp.set('train', params.train.trim());
  if (params.classCode) sp.set('class', params.classCode.trim());
  if (params.action) sp.set('action', params.action.trim());

  const query = sp.toString();
  return query ? `/?${query}` : '/';
}

