import { Metadata } from "next";
import Link from "next/link";
import { Compass } from "lucide-react";

export const metadata: Metadata = {
  title: "Page Not Found | Trayago",
  description:
    "This page could not be found. Browse train search, live running status, PNR status and other Trayago tools instead.",
  robots: {
    // Not indexable, but links are followed so crawl equity reaching a dead URL
    // is passed through to the real pages listed below.
    index: false,
    follow: true,
  },
};

// Verified-existing routes only. Every destination here was confirmed present in
// web/src/app during PHASE_SEO-005. Do not add a route to this list without
// checking it exists — a 404 page linking to a 404 is worse than no links.
const DESTINATIONS: { href: string; label: string; description: string }[] = [
  {
    href: "/",
    label: "Train Search",
    description: "Find trains between any two stations",
  },
  {
    href: "/live",
    label: "Live Train Status",
    description: "Current running status and delays",
  },
  {
    href: "/pnr",
    label: "PNR Status",
    description: "Check a booking and confirmation chance",
  },
  {
    href: "/tracker",
    label: "Train Tracker",
    description: "Follow a journey with a destination alarm",
  },
  {
    href: "/ai-waitlist-rescue",
    label: "AI Waitlist Rescue",
    description: "Alternatives when your ticket is waitlisted",
  },
  {
    href: "/news",
    label: "News & Guides",
    description: "Railway updates and travel guides",
  },
];

export default function NotFound() {
  return (
    <div className="min-h-screen bg-app text-main flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Background radial gradient — mirrors the offline shell treatment */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(37,99,235,0.08)_0%,transparent_60%)] pointer-events-none" />

      <div className="w-full max-w-lg bg-card/60 backdrop-blur-xl border border-subtle rounded-3xl p-8 shadow-2xl relative z-10 flex flex-col items-center">
        <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center border border-blue-500/20 mb-6">
          <Compass className="w-10 h-10 text-blue-500" />
        </div>

        <p className="text-muted text-[10px] uppercase font-black tracking-wider mb-2">
          Error 404
        </p>

        <h1 className="text-2xl font-black tracking-tight mb-2 text-main text-center">
          This page could not be found
        </h1>

        <p className="text-secondary text-sm mb-8 leading-relaxed text-center">
          The link may be broken, or the page may have been moved or removed.
          Everything below is still where you expect it.
        </p>

        <nav aria-label="Popular Trayago pages" className="w-full">
          <ul className="w-full flex flex-col gap-2">
            {DESTINATIONS.map((item) => (
              <li key={item.href}>
                <Link
                  href={item.href}
                  className="group w-full flex flex-col gap-0.5 bg-input/50 hover:bg-input border border-subtle hover:border-strong/40 rounded-2xl px-4 py-3 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                >
                  <span className="text-sm font-bold text-main group-hover:text-primary transition-colors">
                    {item.label}
                  </span>
                  <span className="text-xs text-muted">{item.description}</span>
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </div>
  );
}
