"use client";
import React, { useState, useEffect } from "react";
import { X } from "lucide-react";

export default function BetaWidgets() {
  const [betaCode, setBetaCode] = useState<string | null>(null);
  const [showBanner, setShowBanner] = useState(true);

  useEffect(() => {
    try {
      const code = localStorage.getItem("betaCode");
      if (code) {
        setBetaCode(code);
      }
    } catch (e) {
      console.warn("Storage access failed", e);
    }
  }, []);

  if (!betaCode) return null;

  return (
    <>
      {/* 1. Beta Welcome Banner */}
      {showBanner && (
        <div className="fixed top-0 left-0 right-0 bg-gradient-to-r from-indigo-950 via-purple-950 to-indigo-950 text-white text-xs py-2 px-4 flex items-center justify-between gap-4 z-[99999] border-b border-indigo-500/25 shadow-lg font-sans">
          <div className="flex items-center gap-2 mx-auto">
            <span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" />
            <span className="font-semibold text-indigo-300">Beta Tester Access Active:</span>
            <span className="text-gray-300">You have unlimited premium features unlocked. Thank you for testing Trayago!</span>
          </div>
          <button onClick={() => setShowBanner(false)} className="text-white/60 hover:text-white transition p-1 rounded hover:bg-white/10">
            <X size={14} />
          </button>
        </div>
      )}

      {/* Adjust body padding for banner */}
      {showBanner && (
        <style dangerouslySetInnerHTML={{ __html: `
          body {
            padding-top: 32px !important;
          }
        `}} />
      )}

    </>
  );
}
