function getDailyMessage(nowMs: number): DailyMessage {
  const d = new Date(nowMs);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const dateKey = `${year}-${month}-${day}`;

  return (
    DAILY_MESSAGES[dateKey] || {
      badge: "🇮🇳 HAPPY 80TH INDEPENDENCE DAY",
      headline: "15 August 1947: Azaadi Ki Shuruat, Naye Bharat Ka Safar",
      subheadline: "Azadi ke is khas din, Bharat ke har safar aur uski kahaniyon ko explore karein.",
    }
  );
}

function AshokaChakra({ compact = false }: { compact?: boolean }) {
  const spokes = Array.from({ length: 24 });
  return (
    <motion.div
      className={`relative ${compact ? "h-12 w-12" : "h-20 w-20"} shrink-0`}
      animate={{ rotate: 360 }}
      transition={{
        duration: 48,
        ease: "linear",
        repeat: Infinity,
      }}
    >
      <div
        className="absolute inset-0 rounded-full"
        style={{
          background:
            "radial-gradient(circle, rgba(0,0,128,.28), rgba(0,0,128,.06) 50%, transparent 70%)",
          filter: "blur(4px)",
        }}
      />
      <svg
        viewBox="0 0 100 100"
        className="relative z-10 h-full w-full"
        aria-hidden="true"
      >
        <circle
          cx="50"
          cy="50"
          r="38"
          fill="none"
          stroke={TRICOLOR.navy}
          strokeWidth="2.8"
        />
        <circle cx="50" cy="50" r="4" fill={TRICOLOR.navy} />
        {spokes.map((_, index) => {
          const angle = (index * 360) / spokes.length;
          const rad = (angle * Math.PI) / 180;
          const x2 = 50 + Math.cos(rad) * 36;
          const y2 = 50 + Math.sin(rad) * 36;
          return (
            <line
              key={index}
              x1="50"
              y1="50"
              x2={x2}
              y2={y2}
              stroke={TRICOLOR.navy}
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          );
        })}
      </svg>
    </motion.div>
  );
}

