export default function IndependenceCampaignModal() {
  const [isOpen, setIsOpen] = useState(false);
  const [is15August, setIs15August] = useState(false);
  const [stage, setStage] = useState<Stage>("reveal");
  const [dailyMsg, setDailyMsg] = useState<DailyMessage | null>(null);
  const [copied, setCopied] = useState(false);
  const [loading, setLoading] = useState(false);
  const [needsAuth, setNeedsAuth] = useState(false);
  const [statusMsg, setStatusMsg] = useState<{ type: "success" | "error" | "info"; text: string } | null>(null);
  const [isRedeemed, setIsRedeemed] = useState(false);
  const reduceMotion = useReducedMotion();
  // PHASE_020: dedup guard — prevents double redemption if StrictMode fires effect twice
  const pendingClaimAttempted = useRef(false);

  useEffect(() => {
    const now = Date.now();

    // 1. Campaign Date Range Guard: 15 Aug 00:00:00 to 21 Aug 23:59:59 IST
    if (now < CAMPAIGN_START || now > CAMPAIGN_END) {
      return;
    }

    // 2. 15 August Celebration Mode
    const isToday15Aug = now >= CAMPAIGN_START && now <= CELEBRATION_END;
    setIs15August(isToday15Aug);

    // 3. Stage initialization: 15 Aug starts at 'intro'; 16-21 Aug starts directly at 'reveal'
    setStage(isToday15Aug ? "intro" : "reveal");

    // 4. Set deterministic daily message
    setDailyMsg(getDailyMessage(now));

    // 5. Handle post-login pending claim (PHASE_020 — safe retry semantics)
    const pendingClaim = localStorage.getItem("pendingCouponClaim");
    const token = localStorage.getItem("accessToken");
    if (pendingClaim === CAMPAIGN_CODE && token && !pendingClaimAttempted.current) {
      pendingClaimAttempted.current = true;
      axios
        .post(
          `${API_BASE}/beta/redeem`,
          { code: CAMPAIGN_CODE },
          { headers: { Authorization: `Bearer ${token}` } }
        )
        .then((res) => {
          if (res.data.success) {
            // SUCCESS: clear pending claim + show user-facing confirmation
            localStorage.removeItem("pendingCouponClaim");
            setIsRedeemed(true);
            setStatusMsg({
              type: "success",
              text: "🎉 AZADI80 activate ho gaya! Aapko 30 din ka Free Access mil gaya hai.",
            });
          } else {
            // Backend returned success: false — preserve claim for manual retry
            setStatusMsg({
              type: "error",
              text: res.data.message || "Code redeem nahi ho paya. Claim button se phir try karein.",
            });
          }
        })
        .catch((err: any) => {
          const errMsg =
            err.response?.data?.error ||
            err.response?.data?.message ||
            err.message;
          if (errMsg?.includes("already redeemed") || errMsg?.includes("active")) {
            // Backend confirms prior redemption — treat as success
            localStorage.removeItem("pendingCouponClaim");
            setIsRedeemed(true);
            setStatusMsg({
              type: "success",
              text: "✨ Aapka 30 din ka offer pehle se active hai!",
            });
          } else {
            // Network / server error — DO NOT remove pendingCouponClaim.
            // User can retry via the Claim button; claim is preserved.
            setStatusMsg({
              type: "error",
              text: "Redemption mein network error. Claim button se phir try karein.",
            });
          }
        });
    }

    // 6. Check dismissal across all users (allow preview via ?campaign=true)
    const isForced = typeof window !== "undefined" && window.location.search.includes("campaign=true");
    const dismissed = localStorage.getItem(DISMISSAL_KEY);
    if (!dismissed || isForced) {
      const timer = setTimeout(() => setIsOpen(true), 400);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleDismiss = () => {
    localStorage.setItem(DISMISSAL_KEY, "true");
    setIsOpen(false);
  };

  const handleCopyCode = () => {
    if (typeof navigator !== "undefined" && navigator.clipboard) {
      navigator.clipboard.writeText(CAMPAIGN_CODE);
      setCopied(true);
      setTimeout(() => setCopied(false), 2200);
    }
  };

  // PHASE_020: Close modal visually for login redirect WITHOUT writing DISMISSAL_KEY.
  // This allows the campaign to re-appear after the user completes login,
  // so the post-login pending-claim result (success/error) is visible.
  const handleNavToLogin = () => {
    setIsOpen(false);
  };

  const handleClaimOffer = async () => {
    setLoading(true);
    setStatusMsg(null);

    // Check if user is logged in
    const token = typeof window !== "undefined" ? localStorage.getItem("accessToken") : null;
    let userId: string | null = null;
    try {
      const storedUser = localStorage.getItem("user");
      if (storedUser) {
        const parsed = JSON.parse(storedUser);
        userId = parsed.id || null;
      }
    } catch {
      // ignore
    }

    // Case B: Unauthenticated / Logged-out / New visitor
    if (!token && !userId) {
      localStorage.setItem("pendingCouponClaim", CAMPAIGN_CODE);
      setStatusMsg({
        type: "info",
        text: "30 din free access paane ke liye pehle Login ya Sign Up karein.",
      });
      setNeedsAuth(true);
      setLoading(false);
      return;
    }

    // Case A: Authenticated user -> execute backend redemption
    try {
      const headers: Record<string, string> = {};
      if (token) {
        headers["Authorization"] = `Bearer ${token}`;
      }

      const res = await axios.post(
        `${API_BASE}/beta/redeem`,
        {
          code: CAMPAIGN_CODE,
          userId: userId || undefined,
        },
        { headers }
      );

      if (res.data.success) {
        setIsRedeemed(true);
        localStorage.removeItem("pendingCouponClaim");
        setStatusMsg({
          type: "success",
          text: "🎉 Badhaai ho! 30 Din Ka Free Access activate ho gaya hai.",
        });

        setTimeout(() => {
          handleDismiss();
        }, 2200);
      } else {
        setStatusMsg({
          type: "error",
          text: res.data.message || "Code apply nahi ho paya. Kripya dubara koshish karein.",
        });
      }
    } catch (err: any) {
      const errMsg = err.response?.data?.error || err.response?.data?.message || err.message;
      if (errMsg?.includes("already redeemed") || errMsg?.includes("active")) {
        setIsRedeemed(true);
        localStorage.removeItem("pendingCouponClaim");
        setStatusMsg({
          type: "success",
          text: "✨ Aapka 30 din ka offer pehle se active hai!",
        });
        setTimeout(() => handleDismiss(), 2000);
      } else {
        setStatusMsg({
          type: "error",
          text: errMsg || "Redemption me samasya aayi. Kripya dubara try karein.",
        });
      }
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen || !dailyMsg) return null;

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={stage}
        className="fixed inset-0 z-[9999] flex items-center justify-center p-3 sm:p-4 overflow-y-auto bg-black/85 backdrop-blur-xl"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
      >
        {/* Tricolor Atmospheric Lights on 15 August Reveal */}
        {is15August && stage === "reveal" && !reduceMotion && (
          <>
            <motion.div
              className="absolute left-[8%] top-[15%] h-72 w-72 rounded-full blur-[100px] pointer-events-none"
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.3 }}
              transition={{ duration: 1.1 }}
              style={{ background: TRICOLOR.saffron }}
            />
            <motion.div
              className="absolute right-[8%] bottom-[12%] h-72 w-72 rounded-full blur-[100px] pointer-events-none"
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.25 }}
              transition={{ duration: 1.2 }}
              style={{ background: TRICOLOR.green }}
            />
            <motion.div
              className="absolute left-1/2 top-1/2 h-64 w-64 -translate-x-1/2 -translate-y-1/2 rounded-full blur-[110px] pointer-events-none"
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.12 }}
              transition={{ duration: 1.3 }}
              style={{ background: "#FFFFFF" }}
            />
          </>
        )}

        {/* Modal Card Container */}
        <motion.div
          className="relative z-10 w-full max-w-[450px] my-auto"
          initial={{ y: 20, scale: 0.95, opacity: 0 }}
          animate={{ y: 0, scale: 1, opacity: 1 }}
          transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
        >
          <div className="relative overflow-hidden rounded-[30px] border border-white/[0.12] bg-[#0A0C14]/94 shadow-[0_32px_120px_rgba(0,0,0,.75)] backdrop-blur-2xl text-white">
            {/* Top Tricolor Hairline */}
            <div
              className="absolute inset-x-0 top-0 h-[2.5px] z-20"
              style={{
                background:
                  "linear-gradient(90deg, #FF9933 0%, #FF9933 32%, #FFFFFF 50%, #138808 68%, #138808 100%)",
              }}
            />

            {/* Close Button */}
            <button
              type="button"
              aria-label="Close"
              onClick={handleDismiss}
              className="absolute right-3.5 top-3.5 z-30 flex h-8 w-8 items-center justify-center rounded-full border border-white/10 bg-white/[0.06] text-white/70 transition hover:bg-white/[0.14] hover:text-white active:scale-95"
            >
              <X size={16} />
            </button>

            {is15August && stage === "intro" ? (
              /* ===================== 15 AUGUST INTRO: DARK CELESTIAL GLOBE ===================== */
              <div className="flex flex-col items-center justify-center px-6 py-9 text-center sm:px-8">
                {/* Dark Dotted Globe */}
                <div className="relative mb-5 flex h-48 w-48 sm:h-52 sm:w-52 items-center justify-center">
                  {/* Outer rotating ring */}
                  <motion.div
                    className="absolute inset-0 rounded-full"
                    animate={reduceMotion ? undefined : { rotate: 360 }}
                    transition={{ duration: 54, ease: "linear", repeat: Infinity }}
                    style={{
                      background:
                        "radial-gradient(circle at 35% 28%, rgba(255,255,255,.09), rgba(255,255,255,.02) 40%, transparent 68%)",
                      boxShadow:
                        "inset 0 0 0 1px rgba(255,255,255,.08), 0 0 80px rgba(60,100,255,.06)",
                    }}
                  />

                  {/* Inner dark sphere */}
                  <div
                    className="absolute inset-3 rounded-full border border-white/[0.08]"
                    style={{
                      background:
                        "radial-gradient(circle at 42% 32%, rgba(16,20,30,.92), rgba(3,4,8,.98))",
                    }}
                  />

                  {/* Dot field texture */}
                  <div className="absolute inset-7 overflow-hidden rounded-full opacity-45 pointer-events-none">
                    <div
                      className="absolute inset-0"
                      style={{
                        backgroundImage:
                          "radial-gradient(circle, rgba(255,255,255,.5) 1px, transparent 1px)",
                        backgroundSize: "8px 8px",
                        maskImage: "radial-gradient(circle, black 32%, transparent 74%)",
                        WebkitMaskImage: "radial-gradient(circle, black 32%, transparent 74%)",
                      }}
                    />
                  </div>

                  {/* Center Ashoka Chakra */}
                  <AshokaChakra />
                </div>

                <div className="mb-3 inline-flex items-center rounded-full border border-white/10 bg-white/[0.05] px-3.5 py-1 text-[10px] font-semibold tracking-[0.2em] text-amber-300">
                  INDIA • 15 AUGUST
                </div>

                <h2 className="max-w-[340px] text-2xl font-bold leading-tight tracking-tight text-white sm:text-3xl">
                  Azaadi ka safar
                  <span className="mt-1 block text-white/55 font-medium text-lg sm:text-xl">
                    ab ek nayi roshni ke saath.
                  </span>
                </h2>

                <p className="mt-3 max-w-[320px] text-xs sm:text-sm leading-relaxed text-white/55">
                  Aaj sirf offer nahi — Azaadi ke 80 saalon ka ek chhota sa celebration hai.
                </p>

                <motion.button
                  type="button"
                  onClick={() => setStage("reveal")}
                  whileHover={reduceMotion ? undefined : { scale: 1.025 }}
                  whileTap={reduceMotion ? undefined : { scale: 0.975 }}
                  className="group mt-6 inline-flex min-h-12 items-center gap-2.5 rounded-full border border-white/10 bg-white px-7 text-xs sm:text-sm font-bold text-black shadow-[0_14px_45px_rgba(255,255,255,.16)] transition cursor-pointer"
                >
                  <span>Click Here</span>
                  <ArrowRight
                    size={16}
                    className="transition-transform duration-300 group-hover:translate-x-1"
                  />
                </motion.button>

                <p className="mt-3 text-[11px] text-white/35">
                  Tiranga celebration unlock karein
                </p>
              </div>
            ) : (
              /* ===================== REVEAL & DIRECT OFFER STAGE (15–21 AUGUST) ===================== */
              <div className="relative px-5 pb-6 pt-7 sm:px-7 sm:pb-7 text-center">
                {/* 15 August Only: Real India Outline with Tricolor Reveal */}
                {is15August ? (
                  <div className="mb-1 flex items-center justify-center">
                    <RealIndiaRevealGraphic />
                  </div>
                ) : (
                  <div className="mb-3 flex items-center justify-center">
                    <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-amber-500/20 to-amber-600/10 border border-amber-500/30 flex items-center justify-center text-amber-400 shadow-md">
                      <Gift className="w-5 h-5" />
                    </div>
                  </div>
                )}

                {/* Badge */}
                <motion.div
                  className="mx-auto inline-flex items-center rounded-full border border-white/10 bg-white/[0.05] px-3.5 py-1 text-[10px] sm:text-[11px] font-semibold tracking-wider text-amber-300"
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2, duration: 0.4 }}
                >
                  {dailyMsg.badge}
                </motion.div>

                {/* Headline */}
                <motion.h2
                  className="mx-auto mt-2.5 max-w-[360px] text-lg sm:text-xl font-bold tracking-tight text-white leading-snug"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.3, duration: 0.45 }}
                >
                  {dailyMsg.headline}
                </motion.h2>

                {/* Subtext */}
                <motion.p
                  className="mx-auto mt-1.5 max-w-[330px] text-xs sm:text-sm leading-relaxed text-gray-300"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.4, duration: 0.45 }}
                >
                  {dailyMsg.subheadline}
                </motion.p>

                {/* Benefits Chips */}
                <motion.div
                  className="mt-3.5 flex flex-wrap justify-center gap-1.5 sm:gap-2"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.5, duration: 0.45 }}
                >
                  {["AI Split Journeys", "Live Train GPS", "PNR & Seat Check"].map((item) => (
                    <span
                      key={item}
                      className="rounded-lg border border-white/[0.08] bg-white/[0.04] px-2.5 py-1 text-[11px] font-medium text-gray-200 flex items-center gap-1"
                    >
                      <Check className="w-3 h-3 text-emerald-400" /> {item}
                    </span>
                  ))}
                </motion.div>

                {/* Coupon Bar */}
                <motion.div
                  className="mt-4 rounded-2xl border border-white/10 bg-white/[0.04] p-3 hover:border-amber-500/30 transition-colors"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.6, duration: 0.45 }}
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="text-left pl-1">
                      <p className="text-[10px] font-bold tracking-widest uppercase text-amber-400">
                        Coupon Code • 30 Din Free
                      </p>
                      <p className="mt-0.5 font-mono text-lg sm:text-xl font-extrabold tracking-wider text-white">
                        {CAMPAIGN_CODE}
                      </p>
                    </div>
                    <button
                      type="button"
                      onClick={handleCopyCode}
                      className="inline-flex min-h-9 items-center gap-1.5 rounded-xl border border-white/10 bg-white/[0.08] hover:bg-white/[0.15] px-3 text-xs font-semibold text-gray-200 transition active:scale-95 cursor-pointer"
                    >
                      {copied ? (
                        <Check className="w-3.5 h-3.5 text-emerald-400" />
                      ) : (
                        <Copy className="w-3.5 h-3.5 text-gray-300" />
                      )}
                      <span>{copied ? "Copied" : "Copy Code"}</span>
                    </button>
                  </div>
                </motion.div>

                {/* Status Message */}
                {statusMsg && (
                  <motion.div
                    initial={{ opacity: 0, y: -4 }}
                    animate={{ opacity: 1, y: 0 }}
                    className={`mt-3 w-full p-2.5 rounded-xl text-xs font-medium ${
                      statusMsg.type === "success"
                        ? "bg-emerald-500/20 text-emerald-300 border border-emerald-500/30"
                        : statusMsg.type === "error"
                        ? "bg-rose-500/20 text-rose-300 border border-rose-500/30"
                        : "bg-blue-500/20 text-blue-200 border border-blue-500/30"
                    }`}
                  >
                    {statusMsg.text}
                  </motion.div>
                )}

                {/* Primary CTA */}
                <motion.div
                  className="mt-3.5"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.7, duration: 0.45 }}
                >
                  {needsAuth ? (
                    <Link
                      href="/login?claim=AZADI80"
                      onClick={handleNavToLogin}
                      className="flex min-h-12 w-full items-center justify-center gap-2 rounded-2xl px-5 text-xs sm:text-sm font-extrabold text-slate-950 shadow-[0_8px_30px_rgba(255,153,51,.25)] hover:brightness-110 active:scale-[0.98] transition cursor-pointer"
                      style={{
                        background:
                          "linear-gradient(90deg, #FF9933 0%, #FF9933 30%, #FFFFFF 50%, #138808 70%, #138808 100%)",
                      }}
                    >
                      <LogIn className="w-4 h-4 text-slate-950" />
                      Login Karke AZADI80 Claim Karein
                      <ArrowRight className="w-4 h-4 text-slate-950" />
                    </Link>
                  ) : !isRedeemed ? (
                    <motion.button
                      type="button"
                      onClick={handleClaimOffer}
                      disabled={loading}
                      whileHover={reduceMotion ? undefined : { scale: 1.015 }}
                      whileTap={reduceMotion ? undefined : { scale: 0.985 }}
                      className="flex min-h-12 w-full items-center justify-center gap-2 rounded-2xl px-5 text-xs sm:text-sm font-extrabold text-slate-950 shadow-[0_8px_30px_rgba(255,153,51,.25)] hover:brightness-110 active:scale-[0.98] transition disabled:opacity-50 cursor-pointer"
                      style={{
                        background:
                          "linear-gradient(90deg, #FF9933 0%, #FF9933 30%, #FFFFFF 50%, #138808 70%, #138808 100%)",
                      }}
                    >
                      {loading ? (
                        <span className="inline-block w-4 h-4 border-2 border-slate-950 border-t-transparent rounded-full animate-spin" />
                      ) : (
                        <>
                          <Sparkles className="w-4 h-4 text-slate-950" />
                          AZADI80 Claim Karein (30 Din Free)
                          <ArrowRight className="w-4 h-4 text-slate-950" />
                        </>
                      )}
                    </motion.button>
                  ) : (
                    <button
                      type="button"
                      onClick={handleDismiss}
                      className="flex min-h-12 w-full items-center justify-center gap-2 rounded-2xl bg-emerald-500 hover:bg-emerald-600 active:scale-[0.98] px-5 text-xs sm:text-sm font-bold text-slate-950 transition cursor-pointer shadow-md"
                    >
                      <Check className="w-4 h-4" />
                      Access Shuru — Search Karein
                    </button>
                  )}
                </motion.div>

                {/* Footer Trust Line */}
                <p className="mt-3 text-center text-[10px] leading-4 text-white/35">
                  AZADI80 redeem karein • 30 din ka free access • No credit card
                </p>
              </div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
