"use client";

import React, { useEffect, useState, useCallback } from "react";
import { AlertTriangle, Clock, X, Info } from "lucide-react";
import { getIstAdvisoryStatus, IstAdvisoryStatus } from "@/lib/istTimeUtils";

interface IrctcServiceAdvisoryBannerProps {
  /**
   * 'banner': Sticky top banner across pages.
   * 'inline': Contextual alert card within specific page flows (e.g. PNR, Seat Availability).
   */
  variant?: "banner" | "inline";
  className?: string;
}

const STORAGE_PREFIX = "trayago_irctc_advisory_dismissed_";

export default function IrctcServiceAdvisoryBanner({
  variant = "banner",
  className = ""
}: IrctcServiceAdvisoryBannerProps) {
  const [advisory, setAdvisory] = useState<IstAdvisoryStatus>({
    isActive: false,
    type: null,
    title: "",
    message: "",
    windowLabel: ""
  });
  const [isDismissed, setIsDismissed] = useState<boolean>(true); // start hidden to prevent hydration flicker

  const checkStatus = useCallback(() => {
    try {
      const current = getIstAdvisoryStatus();
      setAdvisory(current);

      if (!current.isActive || !current.type) {
        setIsDismissed(true);
        return;
      }

      // Check sessionStorage for dismissal (scoped by variant so inline warnings remain active)
      const dismissedKey = `${STORAGE_PREFIX}${variant}_${current.type}`;
      const wasDismissed = typeof window !== "undefined" && sessionStorage.getItem(dismissedKey) === "true";
      setIsDismissed(wasDismissed);
    } catch {
      // Graceful fallback: never crash page if storage/time check fails
      setIsDismissed(true);
    }
  }, [variant]);

  useEffect(() => {
    // Initial evaluation on mount
    checkStatus();

    // 60-second periodic refresh to transition in/out of advisory windows
    const interval = setInterval(checkStatus, 60000);
    return () => clearInterval(interval);
  }, [checkStatus]);

  const handleDismiss = () => {
    if (!advisory.type) return;
    try {
      const dismissedKey = `${STORAGE_PREFIX}${variant}_${advisory.type}`;
      sessionStorage.setItem(dismissedKey, "true");
    } catch {}
    setIsDismissed(true);
  };

  if (!advisory.isActive || isDismissed) {
    return null;
  }

  const isNight = advisory.type === "NIGHT_MAINTENANCE";

  // INLINE VARIANT (e.g. for PNR Status check or Seat Availability cards)
  if (variant === "inline") {
    return (
      <div
        role="alert"
        aria-live="polite"
        className={`relative overflow-hidden rounded-2xl border p-4 transition-all duration-200 shadow-sm ${
          isNight
            ? "border-amber-500/25 bg-amber-50/95 text-amber-950 dark:border-amber-500/30 dark:bg-amber-950/40 dark:text-amber-100"
            : "border-blue-500/25 bg-blue-50/95 text-blue-950 dark:border-blue-500/30 dark:bg-blue-950/40 dark:text-blue-100"
        } ${className}`}
      >
        <div className="flex items-start gap-3.5">
          <div className="mt-0.5 flex-shrink-0">
            {isNight ? (
              <div className="w-8 h-8 rounded-xl bg-amber-500/20 text-amber-700 dark:text-amber-400 flex items-center justify-center">
                <Clock className="h-4.5 w-4.5 animate-pulse" />
              </div>
            ) : (
              <div className="w-8 h-8 rounded-xl bg-blue-500/20 text-blue-700 dark:text-blue-400 flex items-center justify-center">
                <Info className="h-4.5 w-4.5" />
              </div>
            )}
          </div>
          <div className="flex-1 text-xs md:text-sm leading-relaxed">
            <div className="font-bold flex items-center gap-2 mb-1 flex-wrap">
              <span className="font-black text-sm">{advisory.title}</span>
              <span className="text-[10px] font-mono uppercase px-2 py-0.5 rounded-md bg-amber-500/20 text-amber-800 dark:text-amber-300 font-extrabold border border-amber-500/30">
                {isNight ? "🌙 Night Window: " : "ℹ️ Window: "}{advisory.windowLabel}
              </span>
            </div>
            <p className="opacity-95 text-xs sm:text-sm mt-0.5">{advisory.message}</p>
          </div>
          <button
            onClick={handleDismiss}
            aria-label="Dismiss IRCTC service advisory"
            className="flex-shrink-0 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-xl text-muted-foreground hover:bg-black/10 dark:hover:bg-white/10 hover:text-foreground transition active:scale-95 cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      </div>
    );
  }

  // BANNER VARIANT (Sticky top notification below navbar)
  return (
    <aside
      role="alert"
      aria-live="polite"
      aria-label="IRCTC Service Advisory"
      className={`relative z-40 w-full border-b backdrop-blur-md px-4 py-2.5 transition-all duration-300 shadow-sm ${
        isNight
          ? "border-amber-500/25 bg-amber-50/95 text-amber-950 dark:border-amber-500/30 dark:bg-amber-950/60 dark:text-amber-100"
          : "border-blue-500/25 bg-blue-50/95 text-blue-950 dark:border-blue-500/30 dark:bg-blue-950/60 dark:text-blue-100"
      } ${className}`}
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between gap-3 text-xs md:text-sm">
        <div className="flex items-center gap-2.5 min-w-0">
          <span className="flex-shrink-0">
            {isNight ? (
              <AlertTriangle className="h-4 w-4 text-amber-600 dark:text-amber-400" />
            ) : (
              <Clock className="h-4 w-4 text-blue-600 dark:text-blue-400" />
            )}
          </span>
          <span className="font-extrabold truncate hidden sm:inline px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-800 dark:text-amber-300 text-[10px] uppercase font-mono">
            {advisory.windowLabel}
          </span>
          <p className="truncate sm:whitespace-normal leading-tight font-medium">
            {advisory.message}
          </p>
        </div>
        <button
          onClick={handleDismiss}
          aria-label="Dismiss advisory banner"
          title="Dismiss advisory"
          className="flex-shrink-0 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-xl hover:bg-black/10 dark:hover:bg-white/10 transition active:scale-90 cursor-pointer"
        >
          <X className="h-4 w-4" />
        </button>
      </div>
    </aside>
  );
}
