/**
 * Client-Side Device Identity Management
 * 
 * Provides stable, persistent guest device identification.
 * Generates and stores deviceId in localStorage and fallback cookies.
 */

const DEVICE_ID_KEY = 'deviceId';
const DEVICE_COOKIE_NAME = 'trayago_did';

function isValidDeviceId(id: string | null | undefined): boolean {
  if (!id || typeof id !== 'string') return false;
  const trimmed = id.trim();
  // Safe device ID: length between 10 and 128 chars, alphanumeric, underscores, hyphens
  if (trimmed.length < 10 || trimmed.length > 128) return false;
  if (!/^[a-zA-Z0-9_\-]+$/.test(trimmed)) return false;
  // Exclude placeholder or malformed strings
  if (/^(null|undefined|none|guest|anonymous|\[object Object\])$/i.test(trimmed)) return false;
  return true;
}

function generateCryptographicDeviceId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return `dev_${crypto.randomUUID()}`;
  }
  // Fallback random generation
  const rand = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
  const timestamp = Date.now().toString(36);
  return `dev_${timestamp}_${rand}`;
}

function getCookie(name: string): string | null {
  if (typeof document === 'undefined') return null;
  const match = document.cookie.match(new RegExp('(?:^|; )' + name.replace(/([.$?*|{}()[\]\\/+^])/g, '\\$1') + '=([^;]*)'));
  return match ? decodeURIComponent(match[1]) : null;
}

function setCookie(name: string, value: string, days = 365): void {
  if (typeof document === 'undefined') return;
  const maxAge = days * 24 * 60 * 60;
  document.cookie = `${name}=${encodeURIComponent(value)}; path=/; max-age=${maxAge}; SameSite=Lax`;
}

export function getOrCreateDeviceId(): string {
  if (typeof window === 'undefined') {
    return 'dev_ssr_placeholder';
  }

  // 1. Try localStorage
  try {
    const existingLocal = localStorage.getItem(DEVICE_ID_KEY);
    if (isValidDeviceId(existingLocal)) {
      // Sync to cookie for server-side availability
      setCookie(DEVICE_COOKIE_NAME, existingLocal!);
      return existingLocal!;
    }
  } catch (e) {
    // Storage access may fail in incognito/restricted mode
  }

  // 2. Try cookie fallback
  try {
    const existingCookie = getCookie(DEVICE_COOKIE_NAME);
    if (isValidDeviceId(existingCookie)) {
      try {
        localStorage.setItem(DEVICE_ID_KEY, existingCookie!);
      } catch {}
      return existingCookie!;
    }
  } catch (e) {}

  // 3. Generate new stable ID
  const newId = generateCryptographicDeviceId();

  try {
    localStorage.setItem(DEVICE_ID_KEY, newId);
  } catch {}

  try {
    setCookie(DEVICE_COOKIE_NAME, newId);
  } catch {}

  return newId;
}

