import enCommon from '../locales/en/common.json';
import enTrains from '../locales/en/trains.json';
import enSuperapp from '../locales/en/superapp.json';

// Combine English translations statically to derive keys at compile time
export const enStatic = {
  ...enCommon,
  ...enTrains,
  ...enSuperapp
};

export type Language = 'en' | 'hi' | 'mr' | 'gu' | 'bn' | 'ta' | 'te' | 'kn' | 'or';
export type TranslationKey = keyof typeof enStatic;

// Dynamic namespace loader
export async function loadLanguagePack(lang: Language): Promise<Record<string, string>> {
  try {
    if (lang === 'en') {
      return enStatic;
    }
    
    if (lang === 'hi') {
      // Lazy-load Hindi via dynamic imports
      const [common, trains, superapp] = await Promise.all([
        import('../locales/hi/common.json'),
        import('../locales/hi/trains.json'),
        import('../locales/hi/superapp.json')
      ]);

      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'mr') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/mr/common.json'),
        import('../locales/mr/trains.json'),
        import('../locales/mr/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'gu') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/gu/common.json'),
        import('../locales/gu/trains.json'),
        import('../locales/gu/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'bn') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/bn/common.json'),
        import('../locales/bn/trains.json'),
        import('../locales/bn/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'ta') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/ta/common.json'),
        import('../locales/ta/trains.json'),
        import('../locales/ta/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'te') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/te/common.json'),
        import('../locales/te/trains.json'),
        import('../locales/te/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'kn') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/kn/common.json'),
        import('../locales/kn/trains.json'),
        import('../locales/kn/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    if (lang === 'or') {
      const [common, trains, superapp] = await Promise.all([
        import('../locales/or/common.json'),
        import('../locales/or/trains.json'),
        import('../locales/or/superapp.json')
      ]);
      return {
        ...common.default,
        ...trains.default,
        ...superapp.default
      };
    }

    return enStatic;
  } catch (err) {
    console.error(`Failed to load translation pack for: ${lang}`, err);
    return enStatic; // fallback to English
  }
}
